+// A constant function body needs no substitution when its binder is applied.
+const CONSTANT_BODIES = new WeakMap<HBody, HTerm>();
+function constant_body(t: HTerm): HBody {
+  const f = (_x: HTerm): HTerm => t;
+  CONSTANT_BODIES.set(f, t);
+  return f;
+}
